ALTER POLICY comm_files_read ON storage.objects USING(bucket_id='communication-files' AND EXISTS(SELECT 1 FROM public.comm_conversations c WHERE c.id::text=split_part(storage.objects.name,'/',1) AND public.comm_access(c.id)));
ALTER POLICY comm_files_upload ON storage.objects WITH CHECK(bucket_id='communication-files' AND split_part(storage.objects.name,'/',2)=auth.uid()::text AND EXISTS(SELECT 1 FROM public.comm_conversations c WHERE c.id::text=split_part(storage.objects.name,'/',1) AND public.comm_access(c.id)));
ALTER POLICY comm_files_remove ON storage.objects USING(bucket_id='communication-files' AND split_part(storage.objects.name,'/',2)=auth.uid()::text AND EXISTS(SELECT 1 FROM public.comm_conversations c WHERE c.id::text=split_part(storage.objects.name,'/',1) AND public.comm_access(c.id)));